import {collectionPhotos as photos} from './collections-data.js?v=collections-1';
const groups=[['all','全部收藏','전체 컬렉션'],['spaces','收藏空间','컬렉션 공간'],['city','城市街景','도시 풍경'],['fantasy','魔法与中土','마법과 중간계'],['heroes','超级英雄','슈퍼 히어로'],['cars','机械与超跑','자동차'],['disney','童话城堡','동화 성'],['figures','小人仔','미니피겨'],['art','积木艺术','브릭 아트']];
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const tr=(lang,a,b)=>lang==='ko'?b:a;let filter='all',currentLocale='zh',lightboxList=[],lightboxIndex=0;
function crop(p,extra=''){return `<div class="collection-crop" style="--ratio:${p.width/(p.bottom-p.top)};--offset:${-100*p.top/(p.bottom-p.top)}%" ${extra}><img src="${p.src}" alt="${esc(p[currentLocale])}" loading="lazy" decoding="async" width="${p.width}" height="${p.height}"></div>`}
function card(p,i){return `<button type="button" class="collection-card" data-collection="${p.id}">${crop(p)}<span class="collection-caption"><span>${esc(p[currentLocale])}</span><small>${String(i+1).padStart(2,'0')} ↗</small></span></button>`}
export function collectionHome(lang){currentLocale=lang;return `<section class="collection-home" aria-label="${tr(lang,'玩家收藏展示','컬렉션 갤러리')}"><div class="collection-heading"><div><span class="eyebrow">THE COLLECTOR'S CORNER</span><h2>${tr(lang,'收藏，也是一种生活。','컬렉션, 또 하나의 일상.')}<span>.</span></h2><p>${tr(lang,'走进玩家的收藏空间，发现积木之外的灵感。','컬렉터의 공간에서 브릭 너머의 영감을 발견하세요.')}</p></div><a href="#collections" class="secondary">${tr(lang,'查看全部 34 张','사진 34장 모두 보기')} ↗</a></div><div class="collection-preview">${[24,10,17,29,33,1].map((i,n)=>card(photos[i],n)).join('')}</div><p class="collection-credit">${tr(lang,'玩家收藏展示 · 图片由用户提供，保留原图署名','컬렉션 갤러리 · 사용자 제공 사진, 원본 크레딧 유지')}</p></section>`}
export function collectionPage(lang){currentLocale=lang;const list=filter==='all'?photos:photos.filter(p=>p.group===filter);return `<section class="collection-page"><a class="collection-back" href="#home">← ${tr(lang,'返回首页','홈으로')}</a><div class="collection-page-heading"><div><span class="eyebrow">THE COLLECTOR'S CORNER</span><h1>${tr(lang,'把热爱，<br><em>搭成生活。</em>','좋아하는 마음을,<br><em>일상으로 조립해요.</em>')}</h1></div><div class="collection-intro"><p>${tr(lang,'每一个收藏角落，都有自己的故事。<br>从一座城堡到一整面收藏墙，看看玩家如何安放热爱。','모든 컬렉션 공간에는 이야기가 있습니다.<br>하나의 성부터 벽을 채운 컬렉션까지, 취미를 담은 공간을 만나보세요.')}</p><span>34 ${tr(lang,'幅收藏影像','장의 컬렉션 사진')} · ${tr(lang,'点击图片放大欣赏','사진을 눌러 크게 보기')}</span></div></div><div class="collection-filters" role="group" aria-label="${tr(lang,'收藏主题','컬렉션 주제')}">${groups.map(([id,zh,ko])=>`<button type="button" data-collection-filter="${id}" aria-pressed="${filter===id}" class="${filter===id?'active':''}">${tr(lang,zh,ko)}</button>`).join('')}</div><div class="collection-wall">${list.map(card).join('')}</div><p class="collection-credit">${list.length} ${tr(lang,'张图片 · 图片由用户提供，保留原图署名。','장의 사진 · 사용자 제공 사진, 원본 크레딧 유지.')}</p></section>`}
function getDialog(){let d=document.querySelector('#collectionLightbox');if(!d){d=document.createElement('dialog');d.id='collectionLightbox';d.addEventListener('close',()=>document.documentElement.classList.remove('collection-viewing'));d.addEventListener('click',e=>{if(e.target===d)d.close()});document.body.append(d)}return d}
function showPhoto(){const p=lightboxList[lightboxIndex],d=getDialog();d.innerHTML=`<div class="collection-lightbox-top"><span>${lightboxIndex+1} / ${lightboxList.length}</span><button type="button" data-collection-close aria-label="${tr(currentLocale,'关闭','닫기')}">×</button></div><div class="collection-lightbox-image" style="width:min(100%,${72*p.width/(p.bottom-p.top)}vh)">${crop(p)}</div><div class="collection-lightbox-bottom"><button type="button" data-collection-prev aria-label="${tr(currentLocale,'上一张','이전 사진')}">←</button><div><h2>${esc(p[currentLocale])}</h2><p>${tr(currentLocale,'玩家收藏展示','컬렉션 갤러리')}</p></div><button type="button" data-collection-next aria-label="${tr(currentLocale,'下一张','다음 사진')}">→</button></div>`;d.querySelector('img').loading='eager';if(!d.open)d.showModal();document.documentElement.classList.add('collection-viewing')}
document.addEventListener('click',e=>{const card=e.target.closest('[data-collection]');if(card){const onGallery=location.hash==='#collections';lightboxList=onGallery?(filter==='all'?photos:photos.filter(p=>p.group===filter)):photos;lightboxIndex=lightboxList.findIndex(p=>p.id===card.dataset.collection);showPhoto();return}const b=e.target.closest('button');if(!b)return;if(b.dataset.collectionFilter){filter=b.dataset.collectionFilter;document.querySelector('#app').innerHTML=collectionPage(currentLocale)}if(b.hasAttribute('data-collection-close'))getDialog().close();if(b.hasAttribute('data-collection-prev')){lightboxIndex=(lightboxIndex-1+lightboxList.length)%lightboxList.length;showPhoto()}if(b.hasAttribute('data-collection-next')){lightboxIndex=(lightboxIndex+1)%lightboxList.length;showPhoto()}});
document.addEventListener('keydown',e=>{if(!document.querySelector('#collectionLightbox')?.open)return;if(e.key==='ArrowLeft'||e.key==='ArrowRight'){e.preventDefault();lightboxIndex=(lightboxIndex+(e.key==='ArrowRight'?1:-1)+lightboxList.length)%lightboxList.length;showPhoto()}});
window.addEventListener('hashchange',()=>document.querySelector('#collectionLightbox')?.close());
